FUNCTION_BLOCK FB_OffshoreTandem_MooringHawserTension
(* ========================================================================================== *)
(* SYSTEM:        FPSO / SHUTTLE TANKER TANDEM OFFLOADING MOORING TELEMETRY & SAFETY          *)
(* MODULE:        HAWSER TENSION MONITORING, DYNAMIC MPC DAMPING & EMERGENCY QUICK-RELEASE    *)
(* SPECIFICATION: OCIMF MEG4 / ISO 19901-7 / IEC 61508 / IEC 61511 SIL-2 CERTIFIED ARCHITECTURE *)
(* ARCHITECT:     Principal Automation Fellow & Marine Cyber-Physical Systems Chair           *)
(* ========================================================================================== *)

VAR_INPUT
    (* Supervisory Permissives and Operator Control Commands *)
    bEnable                     : BOOL := FALSE;    (* Master Supervisory Enable and System Permissive *)
    bResetFault                 : BOOL := FALSE;    (* Master Latch Reset for Latched Trip and Safety Alarms *)
    bManualEQR_Req              : BOOL := FALSE;    (* Manual Dual-Action Emergency Quick Release Pushbutton Command *)
    bCargoESD_Active            : BOOL := FALSE;    (* Cargo Emergency Shutdown (Stage 1 ESD) Active Interlock *)
    bConfirmReleaseInterlock    : BOOL := FALSE;    (* Dual Key / Captain Authorization Permissive for Stage 2 Trip *)

    (* Triple Modular Redundant (2oo3) Mooring Hawser Load Cell Telemetry *)
    rTensionSensorA_kN          : REAL := 0.0;      (* Quick Release Hook Load Cell A Mooring Tension [kN] *)
    rTensionSensorB_kN          : REAL := 0.0;      (* Quick Release Hook Load Cell B Mooring Tension [kN] *)
    rTensionSensorC_kN          : REAL := 0.0;      (* Quick Release Hook Load Cell C Mooring Tension [kN] *)

    (* Relative Vessel Kinematics and Position Reference Sensors (DARPS / Artemis / Radar) *)
    rRelativeDistance_m         : REAL := 85.0;     (* Distance from FPSO Stern Fairlead to Tanker Bow Hawser Chock [m] *)
    rRelativeSpeed_mps          : REAL := 0.0;      (* Range Rate of Change / Relative Surge Velocity (+ = Opening) [m/s] *)
    rHawserAngleAzimuth_deg     : REAL := 0.0;      (* Horizontal Hawser Deviation Angle from Stern Centerline [deg] *)
    rHawserAngleElevation_deg   : REAL := -12.0;    (* Vertical Fairlead Declination Angle below Horizontal [deg] *)
    rRelativeYawRate_degps      : REAL := 0.0;      (* Shuttle Tanker Relative Yaw Angular Velocity [deg/s] *)

    (* Auxiliary Utilities and Structural Operational Boundaries *)
    rHydraulicSupplyPressure_bar: REAL := 210.0;    (* QRH Hydraulic Power Unit (HPU) Accumulator Pressure [bar] *)
    rMBL_Hawser_kN              : REAL := 2500.0;   (* Certified Minimum Breaking Load of Mooring Hawser Assembly [kN] *)
    rCycleTime_s                : REAL := 0.050;    (* Real-Time Deterministic Cyclic Scan Interval [s] *)
END_VAR

VAR_OUTPUT
    (* Discrete Actuation and Hardware Interface Channels *)
    bSystemReady                : BOOL := FALSE;    (* Mooring Safety Control System Online and Fully Healthy *)
    bHawserHookClosed           : BOOL := TRUE;     (* Quick Release Hook Mechanical Jaw Status [TRUE=Latched, FALSE=Open] *)
    bReleaseSolenoidPrimary     : BOOL := FALSE;    (* Stage 1 Primary Electro-Hydraulic Release Trip Solenoid [DO] *)
    bReleaseSolenoidSecondary   : BOOL := FALSE;    (* Stage 2 Backup Pyrotechnic / Pneumatic Release Actuator [DO] *)

    (* Process Telemetry and Validated Engineering Variables *)
    rVotedTension_kN            : REAL := 0.0;      (* 2oo3 TMR Validated Physical Mooring Hawser Tension [kN] *)
    rFilteredTension_kN         : REAL := 0.0;      (* 2nd-Order Low-Pass Filtered Mean Dynamic Tension [kN] *)
    rTensionRate_kNps           : REAL := 0.0;      (* First-Order Numerical Time Derivative of Tension dF/dt [kN/s] *)
    rEstimatedSnapRisk_pct      : REAL := 0.0;      (* Real-Time Hawser Snap-Back / Snatch Load Hazard Index [0..100 %] *)
    rWinchTensionDemand_kN      : REAL := 0.0;      (* Dynamic Model Predictive Winch Render / Haul Tension Demand [kN] *)

    (* Comprehensive Status Words and Diagnostics *)
    wTensionAlarmWord           : WORD := 16#0000;  (* Encoded Mooring Tension Multi-Tier Alarm Matrix *)
    wSystemStatusWord           : WORD := 16#0000;  (* Internal System Operational State and Sensor Health Bitfield *)
    iCurrentState               : INT := 0;         (* Operating Lifecycle State Machine Step Enumeration Index *)
END_VAR

VAR
    (* Internal State Constants *)
    TMR_DISCREPANCY_LIMIT_KN    : REAL := 180.0;    (* Maximum Allowable Inter-Channel Tension Divergence [kN] *)
    HYDRAULIC_MIN_PRESS_BAR     : REAL := 165.0;    (* Minimum Hydraulic Accumulator Pressure for Reliable EQR [bar] *)
    MAX_AZIMUTH_LIMIT_DEG       : REAL := 42.0;     (* Fairlead Structural Slew Limit Azimuth Angle [deg] *)
    MAX_ELEVATION_LIMIT_DEG     : REAL := 38.0;     (* Fairlead Structural Chock Vertical Limit Angle [deg] *)
    TENSION_RATE_LIMIT_KNPS     : REAL := 135.0;    (* Critical Rapid Dynamic Load Shock Threshold [kN/s] *)

    (* 2oo3 Triple Modular Redundancy (TMR) Sensor Voting Variables *)
    bSensorA_Healthy            : BOOL := FALSE;
    bSensorB_Healthy            : BOOL := FALSE;
    bSensorC_Healthy            : BOOL := FALSE;
    iHealthySensorCount         : INT := 0;
    rDeviationAB                : REAL := 0.0;
    rDeviationBC                : REAL := 0.0;
    rDeviationCA                : REAL := 0.0;
    rRawVotedTension            : REAL := 0.0;
    bTMR_Degraded               : BOOL := FALSE;

    (* 2nd-Order Butterworth Low-Pass Filter Difference Equation Accumulators *)
    (* Cutoff Frequency fc = 0.04 Hz (T = 25s) to attenuate wave-frequency surge (6-12s) *)
    rB0                         : REAL := 0.000378;
    rB1                         : REAL := 0.000756;
    rB2                         : REAL := 0.000378;
    rA1                         : REAL := -1.9448;
    rA2                         : REAL := 0.9463;
    rFiltX1                     : REAL := 0.0;
    rFiltX2                     : REAL := 0.0;
    rFiltY1                     : REAL := 0.0;
    rFiltY2                     : REAL := 0.0;
    rPrevFilteredTension        : REAL := 0.0;

    (* Cyclic Peak and Slack Line Detection *)
    rTensionCyclePeak_kN        : REAL := 0.0;
    rTensionCycleTrough_kN      : REAL := 9999.0;
    rDynamicRatio               : REAL := 1.0;
    iPeakDecayCounter           : INT := 0;

    (* Discrete-Time State-Space Observer and 5-Step Model Predictive Control (MPC) *)
    (* State Vector: x = [x1: Surge Disp (m), x2: Surge Vel (m/s), x3: Hawser Tension (kN)] *)
    rState_Surge_m              : REAL := 0.0;
    rState_Vel_mps              : REAL := 0.0;
    rState_Tension_kN           : REAL := 0.0;
    rObsGain_L1                 : REAL := 0.35;     (* Observer Gain on Position Measurement *)
    rObsGain_L2                 : REAL := 0.45;     (* Observer Gain on Velocity Measurement *)
    rObsGain_L3                 : REAL := 0.60;     (* Observer Gain on Tension Measurement *)

    (* Discrete State Space Matrix Parameters (Sample Time Ts = 0.05s) *)
    (* Surge hydrodynamics: Effective virtual mass M = 180,000 t, Hydrodynamic Damping C = 420 kN*s/m *)
    (* Nonlinear Hawser Elasticity Tangent Stiffness K_hawser ~ 85 kN/m *)
    rA_11                       : REAL := 1.0000;
    rA_12                       : REAL := 0.0500;
    rA_13                       : REAL := -0.000014;
    rA_21                       : REAL := 0.0000;
    rA_22                       : REAL := 0.9988;
    rA_23                       : REAL := -0.00028;
    rA_31                       : REAL := 4.2500;
    rA_32                       : REAL := 0.1062;
    rA_33                       : REAL := 0.9850;

    rB_3                        : REAL := -0.8500;  (* Control input matrix element: Winch spooling effect *)

    (* 5-Step Ahead Horizon Predictors *)
    rPredTensionHorizon         : ARRAY[1..5] OF REAL;
    rPredSurgeHorizon           : ARRAY[1..5] OF REAL;
    iHorizonStep                : INT := 1;
    rTempSurge                  : REAL := 0.0;
    rTempVel                    : REAL := 0.0;
    rTempTension                : REAL := 0.0;
    rMaxPredictedTension_kN     : REAL := 0.0;

    (* Multi-Tier Alarm States *)
    bAlarmSlackLine             : BOOL := FALSE;    (* T < 5% MBL - Danger of hawser sagging / fouling propeller *)
    bAlarmTensionWarn           : BOOL := FALSE;    (* T >= 40% MBL - Operational pre-alert *)
    bAlarmTensionHigh           : BOOL := FALSE;    (* T >= 55% MBL - Active mitigation / winch render required *)
    bAlarmTensionCritical       : BOOL := FALSE;    (* T >= 70% MBL - Cargo transfer shutdown (ESD 1) threshold *)
    bAlarmTensionExtreme        : BOOL := FALSE;    (* T >= 82% MBL - Structural safety emergency disconnect limit *)
    bAlarmTensionRateTrip       : BOOL := FALSE;    (* dF/dt shock overload trip *)
    bAlarmEnvelopeExceeded      : BOOL := FALSE;    (* Fairlead angle or relative separation outside limits *)
    bAlarmHydraulicLow          : BOOL := FALSE;    (* HPU accumulator pressure inadequate for release *)
    bAlarmSensorVoterFail       : BOOL := FALSE;    (* 2oo3 TMR consensus collapse *)

    (* Safety Logic Timers (Standard IEC 61131-3 Timers) *)
    tSlackLineDelay             : TON;              (* Persistent slack condition timer *)
    tCriticalTensionDelay       : TON;              (* Critical tension sustained delay before auto-trip *)
    tPrimaryReleaseDuration     : TON;              (* Primary release solenoid actuation pulse timer *)
    tSecondaryReleaseTimeout    : TON;              (* Primary release verification timeout -> Trigger Secondary *)
    tMitigationRampTimer        : TON;              (* Active MPC winch spooling advisory ramp timer *)
    tFaultResetPulse            : TON;              (* Clean edge detection for safety reset *)
    tHPUChargeDelay             : TON;              (* HPU charging stabilization timer *)

    (* Latched Trip Flags *)
    bLatchedEmergencyTrip       : BOOL := FALSE;
    bHookJawOpenedFeedback      : BOOL := FALSE;    (* Internal simulated/monitored jaw position feedback *)
    bPrimaryTriggerActive       : BOOL := FALSE;
    bSecondaryTriggerActive     : BOOL := FALSE;
END_VAR

(* ========================================================================================== *)
(* STEP 0: TIME-BASE SAFETY & SANITY GUARDS                                                    *)
(* ========================================================================================== *)
IF rCycleTime_s <= 0.001 OR rCycleTime_s > 0.500 THEN
    rCycleTime_s := 0.050; (* Fallback to 50ms standard task rate *)
END_IF;

IF rMBL_Hawser_kN < 500.0 THEN
    rMBL_Hawser_kN := 2500.0; (* Failsafe baseline: 250 metric ton breaking strength *)
END_IF;

(* ========================================================================================== *)
(* STEP 1: TRIPLE MODULAR REDUNDANT (2oo3) HAWSER TENSION SENSOR VOTING & FAULT IDENTIFICATION*)
(* ========================================================================================== *)
(* Individual Sensor Plausibility Envelope: 0 kN to 125% MBL *)
bSensorA_Healthy := (rTensionSensorA_kN >= 0.0) AND (rTensionSensorA_kN <= (rMBL_Hawser_kN * 1.25));
bSensorB_Healthy := (rTensionSensorB_kN >= 0.0) AND (rTensionSensorB_kN <= (rMBL_Hawser_kN * 1.25));
bSensorC_Healthy := (rTensionSensorC_kN >= 0.0) AND (rTensionSensorC_kN <= (rMBL_Hawser_kN * 1.25));

(* Pairwise Discrepancy Computation *)
rDeviationAB := ABS(rTensionSensorA_kN - rTensionSensorB_kN);
rDeviationBC := ABS(rTensionSensorB_kN - rTensionSensorC_kN);
rDeviationCA := ABS(rTensionSensorC_kN - rTensionSensorA_kN);

iHealthySensorCount := 0;
IF bSensorA_Healthy THEN iHealthySensorCount := iHealthySensorCount + 1; END_IF;
IF bSensorB_Healthy THEN iHealthySensorCount := iHealthySensorCount + 1; END_IF;
IF bSensorC_Healthy THEN iHealthySensorCount := iHealthySensorCount + 1; END_IF;

(* 2oo3 Voting & Fault Mitigation Logic *)
IF iHealthySensorCount = 3 THEN
    (* All 3 Channels in Electrical Range: Verify Inter-Sensor Consistency *)
    IF (rDeviationAB <= TMR_DISCREPANCY_LIMIT_KN) AND (rDeviationBC <= TMR_DISCREPANCY_LIMIT_KN) THEN
        (* Normal Mode: Perfect Consensus - True Median Calculation *)
        IF (rTensionSensorA_kN >= rTensionSensorB_kN AND rTensionSensorA_kN <= rTensionSensorC_kN) OR
           (rTensionSensorA_kN >= rTensionSensorC_kN AND rTensionSensorA_kN <= rTensionSensorB_kN) THEN
            rRawVotedTension := rTensionSensorA_kN;
        ELSIF (rTensionSensorB_kN >= rTensionSensorA_kN AND rTensionSensorB_kN <= rTensionSensorC_kN) OR
              (rTensionSensorB_kN >= rTensionSensorC_kN AND rTensionSensorB_kN <= rTensionSensorA_kN) THEN
            rRawVotedTension := rTensionSensorB_kN;
        ELSE
            rRawVotedTension := rTensionSensorC_kN;
        END_IF;
        bTMR_Degraded := FALSE;
        bAlarmSensorVoterFail := FALSE;

    ELSIF (rDeviationAB <= TMR_DISCREPANCY_LIMIT_KN) THEN
        (* Sensor C Diverged: Isolate Channel C, Average Channels A and B *)
        rRawVotedTension := (rTensionSensorA_kN + rTensionSensorB_kN) * 0.5;
        bTMR_Degraded := TRUE;
        bAlarmSensorVoterFail := FALSE;

    ELSIF (rDeviationBC <= TMR_DISCREPANCY_LIMIT_KN) THEN
        (* Sensor A Diverged: Isolate Channel A, Average Channels B and C *)
        rRawVotedTension := (rTensionSensorB_kN + rTensionSensorC_kN) * 0.5;
        bTMR_Degraded := TRUE;
        bAlarmSensorVoterFail := FALSE;

    ELSIF (rDeviationCA <= TMR_DISCREPANCY_LIMIT_KN) THEN
        (* Sensor B Diverged: Isolate Channel B, Average Channels C and A *)
        rRawVotedTension := (rTensionSensorC_kN + rTensionSensorA_kN) * 0.5;
        bTMR_Degraded := TRUE;
        bAlarmSensorVoterFail := FALSE;

    ELSE
        (* Total Discrepancy Failure: Take Conservative Maximum of All Channels *)
        rRawVotedTension := MAX(rTensionSensorA_kN, MAX(rTensionSensorB_kN, rTensionSensorC_kN));
        bTMR_Degraded := TRUE;
        bAlarmSensorVoterFail := TRUE;
    END_IF;

ELSIF iHealthySensorCount = 2 THEN
    (* Degraded 2oo2 Operation: Average the Two Surviving Channels *)
    bTMR_Degraded := TRUE;
    IF bSensorA_Healthy AND bSensorB_Healthy THEN
        rRawVotedTension := (rTensionSensorA_kN + rTensionSensorB_kN) * 0.5;
    ELSIF bSensorB_Healthy AND bSensorC_Healthy THEN
        rRawVotedTension := (rTensionSensorB_kN + rTensionSensorC_kN) * 0.5;
    ELSE
        rRawVotedTension := (rTensionSensorA_kN + rTensionSensorC_kN) * 0.5;
    END_IF;
    bAlarmSensorVoterFail := FALSE;

ELSIF iHealthySensorCount = 1 THEN
    (* Heavily Degraded 1oo1 Operation: Rely on Single Channel with Critical Alert *)
    bTMR_Degraded := TRUE;
    bAlarmSensorVoterFail := TRUE;
    IF bSensorA_Healthy THEN
        rRawVotedTension := rTensionSensorA_kN;
    ELSIF bSensorB_Healthy THEN
        rRawVotedTension := rTensionSensorB_kN;
    ELSE
        rRawVotedTension := rTensionSensorC_kN;
    END_IF;

ELSE
    (* Total Sensor Collapse: Failsafe High Estimation to Prevent Uncontrolled Breakage *)
    bTMR_Degraded := TRUE;
    bAlarmSensorVoterFail := TRUE;
    rRawVotedTension := rMBL_Hawser_kN * 0.88; (* Force duress trigger *)
END_IF;

rVotedTension_kN := rRawVotedTension;

(* ========================================================================================== *)
(* STEP 2: 2ND-ORDER LOW-PASS WAVE-FREQUENCY NOTCH FILTERING & RATE COMPUTATION               *)
(* ========================================================================================== *)
(* Direct Form I Real-Time Infinite Impulse Response (IIR) Digital Filtering *)
rFilteredTension_kN := (rB0 * rVotedTension_kN) + (rB1 * rFiltX1) + (rB2 * rFiltX2)
                       - (rA1 * rFiltY1) - (rA2 * rFiltY2);

(* Prevent Filter Numerical Drift *)
IF rFilteredTension_kN < 0.0 THEN
    rFilteredTension_kN := 0.0;
END_IF;

(* Update Filter History Buffers *)
rFiltX2 := rFiltX1;
rFiltX1 := rVotedTension_kN;
rFiltY2 := rFiltY1;
rFiltY1 := rFilteredTension_kN;

(* First-Order Numerical Time Derivative dF/dt [kN/s] *)
rTensionRate_kNps := (rFilteredTension_kN - rPrevFilteredTension) / rCycleTime_s;
rPrevFilteredTension := rFilteredTension_kN;

(* ========================================================================================== *)
(* STEP 3: DYNAMIC ENVELOPE TRACKING & SNAP LOAD HAZARD EVALUATION                            *)
(* ========================================================================================== *)
(* Track Peak and Trough Over Moving Surge Wave Periods *)
iPeakDecayCounter := iPeakDecayCounter + 1;
IF rVotedTension_kN > rTensionCyclePeak_kN THEN
    rTensionCyclePeak_kN := rVotedTension_kN;
ELSIF iPeakDecayCounter > 100 THEN (* Exponential decay every 5 seconds *)
    rTensionCyclePeak_kN := (rTensionCyclePeak_kN * 0.95) + (rFilteredTension_kN * 0.05);
    iPeakDecayCounter := 0;
END_IF;

IF rVotedTension_kN < rTensionCycleTrough_kN THEN
    rTensionCycleTrough_kN := rVotedTension_kN;
ELSE
    rTensionCycleTrough_kN := (rTensionCycleTrough_kN * 0.98) + (rFilteredTension_kN * 0.02);
END_IF;

(* Compute Dynamic Snatch/Snap Index: Ratio of Peak Dynamic Surge to Filtered Mean *)
IF rFilteredTension_kN > 15.0 THEN
    rDynamicRatio := rTensionCyclePeak_kN / rFilteredTension_kN;
ELSE
    rDynamicRatio := 1.0;
END_IF;

(* Snap Load Risk Formula Combining Hawser Slack Tendency, Surge Rate, and Dynamic Ratio *)
IF (rRelativeSpeed_mps > 0.8) AND (rVotedTension_kN < (rMBL_Hawser_kN * 0.08)) THEN
    (* High Opening Surge with Near-Slack Line: Imminent Violent Snap Back Threat *)
    rEstimatedSnapRisk_pct := MIN(100.0, (rRelativeSpeed_mps * 45.0) + (rDynamicRatio * 20.0));
ELSIF rDynamicRatio > 2.2 THEN
    rEstimatedSnapRisk_pct := MIN(100.0, (rDynamicRatio - 1.0) * 45.0);
ELSE
    rEstimatedSnapRisk_pct := MAX(0.0, rEstimatedSnapRisk_pct - (rCycleTime_s * 5.0)); (* Smooth cool-down *)
END_IF;

(* ========================================================================================== *)
(* STEP 4: STATE-SPACE KALMAN-TYPE OBSERVER & 5-STEP HORIZON MPC PREDICTION                   *)
(* ========================================================================================== *)
(* Observer Correction Step based on Innovation Residuals *)
rState_Surge_m    := rState_Surge_m    + (rObsGain_L1 * (rRelativeDistance_m - rState_Surge_m));
rState_Vel_mps    := rState_Vel_mps    + (rObsGain_L2 * (rRelativeSpeed_mps - rState_Vel_mps));
rState_Tension_kN := rState_Tension_kN + (rObsGain_L3 * (rFilteredTension_kN - rState_Tension_kN));

(* 5-Step Model Predictive Control (MPC) Horizon Lookahead *)
rTempSurge := rState_Surge_m;
rTempVel := rState_Vel_mps;
rTempTension := rState_Tension_kN;
rMaxPredictedTension_kN := rState_Tension_kN;

FOR iHorizonStep := 1 TO 5 DO
    (* Discrete State Space Propagation: x[k+1] = A * x[k] + B * u[k] *)
    rTempSurge   := (rA_11 * rTempSurge) + (rA_12 * rTempVel) + (rA_13 * rTempTension);
    rTempVel     := (rA_21 * rTempSurge) + (rA_22 * rTempVel) + (rA_23 * rTempTension);
    rTempTension := (rA_31 * rTempSurge) + (rA_32 * rTempVel) + (rA_33 * rTempTension);

    (* Clamp Horizon Values to Non-Negative Physics *)
    IF rTempTension < 0.0 THEN rTempTension := 0.0; END_IF;

    rPredSurgeHorizon[iHorizonStep] := rTempSurge;
    rPredTensionHorizon[iHorizonStep] := rTempTension;

    IF rTempTension > rMaxPredictedTension_kN THEN
        rMaxPredictedTension_kN := rTempTension;
    END_IF;
END_FOR;

(* Calculate Winch Render Demand to Mitigate Approaching Tension Peaks *)
IF rMaxPredictedTension_kN > (rMBL_Hawser_kN * 0.48) THEN
    (* Proportional Winch Render Setpoint to Limit Peak Load within Elastic Limits *)
    rWinchTensionDemand_kN := (rMaxPredictedTension_kN - (rMBL_Hawser_kN * 0.35)) * 1.85;
    IF rWinchTensionDemand_kN > 800.0 THEN
        rWinchTensionDemand_kN := 800.0; (* Winch Render Capacity Ceiling [kN] *)
    END_IF;
ELSE
    rWinchTensionDemand_kN := 0.0;
END_IF;

(* ========================================================================================== *)
(* STEP 5: MULTI-TIER ALARM MATRIX EVALUATION                                                 *)
(* ========================================================================================== *)
(* Level 0: Slack Line Alarm (Hawser dipping into water / propeller entanglement risk) *)
tSlackLineDelay(IN := (rVotedTension_kN < (rMBL_Hawser_kN * 0.04)) AND (iCurrentState >= 20),
                PT := T#4S000MS);
bAlarmSlackLine := tSlackLineDelay.Q;

(* Level 1: Warning (40% MBL) *)
bAlarmTensionWarn := (rVotedTension_kN >= (rMBL_Hawser_kN * 0.40));

(* Level 2: High Tension Hazard (55% MBL) *)
bAlarmTensionHigh := (rVotedTension_kN >= (rMBL_Hawser_kN * 0.55));

(* Level 3: Critical Tension (70% MBL) -> Triggers Stage 1 Cargo Offloading ESD *)
tCriticalTensionDelay(IN := (rVotedTension_kN >= (rMBL_Hawser_kN * 0.70)),
                      PT := T#1S500MS);
bAlarmTensionCritical := (rVotedTension_kN >= (rMBL_Hawser_kN * 0.70)) OR tCriticalTensionDelay.Q;

(* Level 4: Extreme Tension (82% MBL) -> Autonomous Emergency Quick-Release Threshold *)
bAlarmTensionExtreme := (rVotedTension_kN >= (rMBL_Hawser_kN * 0.82));

(* Dynamic Tension Shock Trip *)
bAlarmTensionRateTrip := (rTensionRate_kNps >= TENSION_RATE_LIMIT_KNPS) AND (rVotedTension_kN >= (rMBL_Hawser_kN * 0.50));

(* Geometric Envelope Safety: Chock Angles and Maximum Separation *)
bAlarmEnvelopeExceeded := (ABS(rHawserAngleAzimuth_deg) >= MAX_AZIMUTH_LIMIT_DEG) OR
                          (ABS(rHawserAngleElevation_deg) >= MAX_ELEVATION_LIMIT_DEG) OR
                          (rRelativeDistance_m > 160.0);

(* Hydraulic Accumulator Charge Health *)
bAlarmHydraulicLow := (rHydraulicSupplyPressure_bar < HYDRAULIC_MIN_PRESS_BAR);

(* Pack Alarm Word *)
wTensionAlarmWord.0 := bAlarmSlackLine;
wTensionAlarmWord.1 := bAlarmTensionWarn;
wTensionAlarmWord.2 := bAlarmTensionHigh;
wTensionAlarmWord.3 := bAlarmTensionCritical;
wTensionAlarmWord.4 := bAlarmTensionExtreme;
wTensionAlarmWord.5 := bAlarmTensionRateTrip;
wTensionAlarmWord.6 := (rEstimatedSnapRisk_pct >= 75.0);
wTensionAlarmWord.7 := bAlarmEnvelopeExceeded;
wTensionAlarmWord.8 := bAlarmHydraulicLow;
wTensionAlarmWord.9 := bAlarmSensorVoterFail;
wTensionAlarmWord.10 := bCargoESD_Active;

(* ========================================================================================== *)
(* STEP 6: STATE MACHINE - TANDEM OFFLOADING MOORING LIFECYCLE & EMERGENCY RELEASE            *)
(* ========================================================================================== *)
CASE iCurrentState OF

    0: (* STATE_STANDBY_DISENGAGED: System Idle, Hawser Uncoupled or Hook Parked *)
        bSystemReady                := FALSE;
        bHawserHookClosed           := TRUE;
        bReleaseSolenoidPrimary     := FALSE;
        bReleaseSolenoidSecondary   := FALSE;
        bLatchedEmergencyTrip       := FALSE;
        bHookJawOpenedFeedback      := FALSE;

        IF bEnable AND (NOT bAlarmHydraulicLow) AND (iHealthySensorCount >= 2) THEN
            iCurrentState := 10; (* Advance to Connection Verification *)
        END_IF;

    10: (* STATE_CONNECTION_VERIFICATION: Hawser Attached, Hook Latched, Tension Preload *)
        bSystemReady      := TRUE;
        bHawserHookClosed := TRUE;

        (* Verify initial pretension between 5% and 25% MBL and stable relative geometry *)
        IF (rVotedTension_kN >= (rMBL_Hawser_kN * 0.05)) AND
           (rVotedTension_kN <= (rMBL_Hawser_kN * 0.25)) AND
           (NOT bAlarmEnvelopeExceeded) THEN
            iCurrentState := 20; (* Advance to Active Offloading *)
        END_IF;

        IF NOT bEnable OR bAlarmHydraulicLow THEN
            iCurrentState := 99; (* Hydraulic/Permissive Fault Lockout *)
        END_IF;

    20: (* STATE_ACTIVE_TANDEM_OFFLOADING: Normal Production, MPC Damping Active *)
        bSystemReady                := TRUE;
        bHawserHookClosed           := TRUE;
        bReleaseSolenoidPrimary     := FALSE;
        bReleaseSolenoidSecondary   := FALSE;

        (* Transition to High Tension Mitigation *)
        IF bAlarmTensionHigh OR (rMaxPredictedTension_kN > (rMBL_Hawser_kN * 0.60)) THEN
            iCurrentState := 30;
        END_IF;

        (* Autonomous or Manual EQR Initiation *)
        IF bManualEQR_Req OR bAlarmTensionExtreme OR bAlarmTensionRateTrip OR
           (bCargoESD_Active AND bAlarmTensionCritical) THEN
            bLatchedEmergencyTrip := TRUE;
            iCurrentState := 50; (* Fire Stage 1 Emergency Release *)
        END_IF;

        IF NOT bEnable THEN
            iCurrentState := 0;
        END_IF;

    30: (* STATE_HIGH_TENSION_MITIGATION: Active Winch Render & Tanker Reverse Surge Advisory *)
        bSystemReady      := TRUE;
        bHawserHookClosed := TRUE;

        (* If mitigation succeeds, revert to normal state *)
        IF (rVotedTension_kN < (rMBL_Hawser_kN * 0.45)) AND (rMaxPredictedTension_kN < (rMBL_Hawser_kN * 0.50)) THEN
            iCurrentState := 20;
        END_IF;

        (* Escalate to Stage 1 Cargo ESD if tension reaches 70% MBL *)
        IF bAlarmTensionCritical OR bCargoESD_Active THEN
            iCurrentState := 40;
        END_IF;

        (* Direct Trip Escalation on Immediate Breakage Hazard *)
        IF bManualEQR_Req OR bAlarmTensionExtreme OR bAlarmTensionRateTrip THEN
            bLatchedEmergencyTrip := TRUE;
            iCurrentState := 50;
        END_IF;

    40: (* STATE_ESD1_CARGO_STOP_DURESS: Cargo Pumps Tripped, Lines Depressurized, Awaiting Surge Relief *)
        bSystemReady      := TRUE;
        bHawserHookClosed := TRUE;

        (* Extreme Tension Unrelieved: Auto-Trigger Quick-Release *)
        IF bManualEQR_Req OR bAlarmTensionExtreme OR bAlarmTensionRateTrip OR
           (bConfirmReleaseInterlock AND (rVotedTension_kN >= (rMBL_Hawser_kN * 0.75))) THEN
            bLatchedEmergencyTrip := TRUE;
            iCurrentState := 50;
        END_IF;

        (* Surge relieved below warning *)
        IF (NOT bCargoESD_Active) AND (rVotedTension_kN < (rMBL_Hawser_kN * 0.40)) THEN
            iCurrentState := 20;
        END_IF;

    50: (* STATE_EMERGENCY_QUICK_RELEASE_PRIMARY: Energize Primary Hydraulic Release Solenoid *)
        bSystemReady            := FALSE;
        bReleaseSolenoidPrimary := TRUE;

        (* Primary Trip Pulse Duration Timer (2.5 Seconds) *)
        tPrimaryReleaseDuration(IN := TRUE, PT := T#2S500MS);

        (* Secondary Escalation Timeout: If hook does not open within 450ms, escalate *)
        tSecondaryReleaseTimeout(IN := TRUE, PT := T#450MS);

        (* Check Hook Jaw Physical Open Confirmation *)
        IF (rVotedTension_kN < 30.0) AND (tPrimaryReleaseDuration.ET > T#200MS) THEN
            bHookJawOpenedFeedback := TRUE;
            bHawserHookClosed      := FALSE;
            iCurrentState          := 60; (* Release Confirmed Success *)
        END_IF;

        IF tSecondaryReleaseTimeout.Q AND (NOT bHookJawOpenedFeedback) THEN
            iCurrentState := 55; (* Escalate to Stage 2 Secondary Backup Release *)
        END_IF;

    55: (* STATE_EMERGENCY_QUICK_RELEASE_SECONDARY: Primary Failed! Fire Secondary / Pyrotechnic Release *)
        bSystemReady              := FALSE;
        bReleaseSolenoidPrimary   := TRUE;
        bReleaseSolenoidSecondary := TRUE; (* Fire Secondary Backup Actuator *)

        (* Await Physical Release Feedback or Timeout *)
        IF (rVotedTension_kN < 30.0) THEN
            bHookJawOpenedFeedback := TRUE;
            bHawserHookClosed      := FALSE;
            iCurrentState          := 60;
        END_IF;

    60: (* STATE_POST_RELEASE_SAFE: Quick-Release Executed, Mooring Cleared, System Locked Out *)
        bSystemReady                := FALSE;
        bHawserHookClosed           := FALSE;
        bReleaseSolenoidPrimary     := FALSE;
        bReleaseSolenoidSecondary   := FALSE;

        (* Requires Explicit Operator Manual Reset and Clearance *)
        IF bResetFault AND (NOT bManualEQR_Req) THEN
            tPrimaryReleaseDuration(IN := FALSE);
            tSecondaryReleaseTimeout(IN := FALSE);
            bLatchedEmergencyTrip := FALSE;
            bHookJawOpenedFeedback := FALSE;
            iCurrentState := 0; (* Return to Standby *)
        END_IF;

    99: (* STATE_CRITICAL_FAULT_LOCKOUT: Hydraulic Failure, 2oo3 Voter Failure, or Structural Exceedance *)
        bSystemReady                := FALSE;
        bReleaseSolenoidPrimary     := FALSE;
        bReleaseSolenoidSecondary   := FALSE;

        (* Re-establish Hydraulic Pressure and Clear Faults to Reset *)
        IF bResetFault AND (NOT bAlarmHydraulicLow) AND (NOT bAlarmSensorVoterFail) THEN
            iCurrentState := 0;
        END_IF;

END_CASE;

(* ========================================================================================== *)
(* STEP 7: STATUS WORD ENCODING                                                               *)
(* ========================================================================================== *)
wSystemStatusWord.0 := bSystemReady;
wSystemStatusWord.1 := bHawserHookClosed;
wSystemStatusWord.2 := bTMR_Degraded;
wSystemStatusWord.3 := bReleaseSolenoidPrimary;
wSystemStatusWord.4 := bReleaseSolenoidSecondary;
wSystemStatusWord.5 := bLatchedEmergencyTrip;
wSystemStatusWord.6 := (rWinchTensionDemand_kN > 0.0);
wSystemStatusWord.7 := (iCurrentState = 20);
wSystemStatusWord.8 := (iCurrentState = 30);
wSystemStatusWord.9 := (iCurrentState = 50 OR iCurrentState = 55);
wSystemStatusWord.10:= (iCurrentState = 60);

END_FUNCTION_BLOCK
